// ===== 黄果短剧 订阅源 登录/线路面板（V1 静态数组 + 动态 viewName，LT/E 双版本兼容）=====
// 免登录站点：本面板只做「发布页→线路池→测速→切换」
function HG_def() { return 'https://thu.qxeylvrkf.cc'; }
function HG_pubDef() { return 'https://huang-guo.pages.dev/publish.js'; }
function HG_pubs() {
  return ['https://huang-guo.pages.dev/publish.js', 'https://huangguoai.pages.dev/publish.js'];
}
function HG_toast(m) {
  try { java.longToast(String(m)); }
  catch (e) { try { java.toast(String(m)); } catch (e2) {} }
}
function HG_trim(u) { return String(u == null ? '' : u).replace(/\/+$/, ''); }
function HG_host(u) { return String(u == null ? '' : u).replace(/^https?:\/\//, '').replace(/\/.*$/, ''); }
function HG_short(x, n) { x = String(x == null ? '' : x); n = n || 16; return x.length > n ? x.substring(0, n) + '…' : x; }
function HG_get(k) { try { return String(source.get(k) || ''); } catch (e) { return ''; } }
function HG_set(k, v) { try { source.put(k, String(v)); } catch (e) {} }
function HG_cur() {
  var v = HG_get('hgRssLine');
  if (v.indexOf('http') !== 0) v = HG_def();
  return HG_trim(v);
}
function HG_list() {
  try {
    var a = JSON.parse(HG_get('hgLines') || '[]');
    return (a && a.length) ? a : [];
  } catch (e) { return []; }
}
function HG_page() { return parseInt(HG_get('hgPage') || '0', 10) || 0; }
function HG_pick(key) {
  try { if (result && result.get) { var v = result.get(key); if (v != null) return String(v); } } catch (e) {}
  try { if (result && result[key] != null) return String(result[key]); } catch (e2) {}
  return '';
}
function HG_savePub() {
  var v = HG_pick('发布页地址');
  if (v.indexOf('http') === 0) HG_set('hgPub', v);
  return '';
}
function HG_re() {
  try { java.reLoginView(true); return ''; } catch (e) {}
  try { java.reLoginView(); return ''; } catch (e2) {}
  HG_toast('请关闭并重新打开本面板以刷新按钮文字');
  return '';
}

// 12 个线路按钮的动态文字
function HG_lineBtn(i) {
  var arr = HG_list();
  var idx = HG_page() * 12 + i;
  if (idx >= arr.length) return '·';
  var u = HG_trim(arr[idx]);
  var h = HG_host(u);
  var ms = HG_get('hgMs_' + h);
  var cur = (HG_host(HG_cur()) === h);
  return (cur ? '▶' : '') + HG_short(h, 15) + (ms && ms !== '0' ? ' ' + ms + 'ms' : (ms === '0' ? ' ✗' : ''));
}

function HG_fetch() {
  var pub = HG_pick('发布页地址');
  if (pub.indexOf('http') !== 0) pub = HG_get('hgPub');
  if (pub.indexOf('http') !== 0) pub = HG_pubDef();
  HG_set('hgPub', pub);
  var pubs = [pub];
  var fb = HG_pubs();
  for (var q = 0; q < fb.length; q++) { if (fb[q] !== pub) pubs.push(fb[q]); }
  var body = '';
  var used = '';
  for (var i = 0; i < pubs.length && body.length < 30; i++) {
    HG_toast('① 正在读取发布页（' + (i + 1) + '/' + pubs.length + '）：' + pubs[i]);
    try { body = String(java.ajax(pubs[i])); used = pubs[i]; } catch (e) { body = ''; }
    if (body && body.indexOf('subdomains') < 0 && body.indexOf('var urls') < 0) body = '';
  }
  if (!body || body.length < 30) { HG_toast('✗ 所有发布页都读取失败，请检查网络或手动填写发布页'); return ''; }
  var roots = [], subs = [];
  var m = body.match(/var\s+urls\s*=\s*\[([\s\S]*?)\]/);
  if (m) {
    var g = m[1].match(/['"][^'"]+['"]/g) || [];
    for (var a = 0; a < g.length; a++) {
      var r = HG_trim(g[a].replace(/['"]/g, ''));
      if (r && roots.indexOf(r) < 0) roots.push(r);
    }
  }
  var m2 = body.match(/var\s+subdomains\s*=\s*\[([\s\S]*?)\]/);
  if (m2) {
    var g2 = m2[1].match(/['"][^'"]+['"]/g) || [];
    for (var b = 0; b < g2.length; b++) {
      var s = g2[b].replace(/['"]/g, '').replace(/^\s+|\s+$/g, '');
      // 发布页注释里有 Xi'an 这种撇号，必须只保留合法子域标签
      if (!/^[a-z0-9][a-z0-9-]{0,20}$/.test(s)) continue;
      if (s && subs.indexOf(s) < 0) subs.push(s);
    }
  }
  if (!roots.length) { HG_toast('✗ 发布页里没解析到域名池，站点可能改版了'); return ''; }
  var arr = [];
  for (var x = 0; x < roots.length; x++) {
    for (var y = 0; y < subs.length; y++) {
      var u = 'https://' + subs[y] + '.' + roots[x];
      if (arr.indexOf(u) < 0) arr.push(u);
    }
  }
  var forever = ['https://huangguoai.com', 'https://huangguoai.ai'];
  for (var z = 0; z < forever.length; z++) { if (arr.indexOf(forever[z]) < 0) arr.push(forever[z]); }
  HG_set('hgLines', JSON.stringify(arr));
  HG_set('hgPage', '0');
  HG_set('hgPub', used);
  HG_toast('② 已获取 ' + arr.length + ' 条线路（' + roots.length + ' 个根域 × ' + subs.length + ' 个子域）\n下一步点「⏱ 测速排序」写入延迟');
  HG_re();
  return '';
}

function HG_test() {
  var arr = HG_list();
  if (!arr.length) { HG_toast('请先点「🧭 一键获取线路」'); return ''; }
  if (arr.length > 60) arr = arr.slice(0, 60);
  HG_toast('① 并发测速 ' + arr.length + ' 条线路…（死线路会单条复查，约 5~15 秒）');
  var scored = [];
  var okN = 0;
  var top = [];
  var CHUNK = 5;
  for (var i = 0; i < arr.length; i += CHUNK) {
    var sub = arr.slice(i, i + CHUNK);
    var urls = [];
    for (var q = 0; q < sub.length; q++) urls.push(HG_trim(sub[q]) + '/robots.txt');
    var rs = null;
    try { rs = java.ajaxAll(urls, true); } catch (e0) { rs = null; }
    for (var k = 0; k < sub.length; k++) {
      var uu = HG_trim(sub[k]);
      var hh = HG_host(uu);
      var ok = false;
      var ms = 999999;
      if (rs && rs[k]) {
        try {
          if (rs[k].code() >= 200 && rs[k].code() < 400 &&
              String(rs[k].body() || '').indexOf('Disallow') >= 0) {
            ok = true;
            ms = parseInt(String(rs[k].callTime()), 10) || 999999;
          }
        } catch (e1) {}
      }
      if (!ok) {
        // 整批里只要有一条网络级失败 ajaxAll 会全批抛异常，这里对失败项逐条复查
        try {
          var r2 = java.connect(urls[k], null, 5000);
          if (r2.code() >= 200 && r2.code() < 400 &&
              String(r2.body() || '').indexOf('Disallow') >= 0) {
            ok = true;
            ms = parseInt(String(r2.callTime()), 10) || 999999;
          }
        } catch (e2) {}
      }
      HG_set('hgMs_' + hh, ok ? String(ms) : '0');
      if (ok) {
        okN++;
        if (top.length < 4) top.push(hh + ' ' + ms + 'ms');
      }
      scored.push({ u: uu, ms: ok ? ms : 999999 });
    }
  }
  scored.sort(function (a, b) { return a.ms - b.ms; });
  var out = [];
  for (var t = 0; t < scored.length; t++) out.push(scored[t].u);
  HG_set('hgLines', JSON.stringify(out));
  HG_set('hgPage', '0');
  HG_toast('② 测速完成：可用 ' + okN + '/' + scored.length + ' 条\n最快：' + (top.length ? top.join('、') : '无') + '\n已按延迟排序，第一页最快');
  HG_re();
  return '';
}

function HG_check() {
  var u = HG_cur();
  HG_toast('正在检查当前线路：' + HG_host(u));
  try {
    var h = String(java.ajax(u + '/robots.txt'));
    var ok1 = h.indexOf('Disallow') >= 0;
    var h2 = String(java.ajax(u + '/newest'));
    var ok2 = h2.indexOf('hg-drama-card') >= 0;
    if (ok1 && ok2) {
      HG_toast('✓ 线路正常：' + HG_host(u) + '\n首页 ' + h2.length + ' 字节；本站免登录，游客可用');
    } else {
      HG_toast('✗ 线路异常：' + HG_host(u) + '\n请点「⏱ 测速排序」换一条');
    }
  } catch (e) {
    HG_toast('✗ 线路不可用：' + HG_short(e, 70) + '\n请点「🧭 一键获取线路」重新取线');
  }
  return '';
}

function HG_switch(i) {
  var arr = HG_list();
  var idx = HG_page() * 12 + i;
  if (idx >= arr.length) { HG_toast('该位置暂无线路'); return ''; }
  var u = HG_trim(arr[idx]);
  var h = HG_host(u);
  HG_set('hgRssLine', u);
  HG_set('hgChk_t', '0');
  var ok = false;
  try { ok = String(java.ajax(u + '/robots.txt')).indexOf('Disallow') >= 0; } catch (e) {}
  HG_toast((ok ? '✓ 线路可用，已切换：' : '⚠ 探活失败，仍已切换：') + h + '\n回到发现/搜索刷新即可生效');
  HG_re();
  return '';
}

function HG_pagePrev() {
  var p = HG_page() - 1;
  if (p < 0) p = 0;
  HG_set('hgPage', String(p));
  HG_re();
  return '';
}

function HG_pageNext() {
  var arr = HG_list();
  var max = Math.max(0, Math.ceil(arr.length / 12) - 1);
  var p = HG_page() + 1;
  if (p > max) { HG_toast('已经是最后一页线路'); p = max; }
  HG_set('hgPage', String(p));
  HG_re();
  return '';
}

function HG_statusName() {
  var h = HG_host(HG_cur());
  var ms = HG_get('hgMs_' + h);
  return '当前 ' + HG_short(h, 14) + (ms ? ' ' + ms + 'ms' : '');
}

function HG_status() {
  var arr = HG_list();
  var ms = HG_get('hgMs_' + HG_host(HG_cur()));
  HG_toast('当前线路：' + HG_host(HG_cur()) + (ms ? '（' + ms + 'ms）' : '') + '\n线路池：' + arr.length + ' 条（第 ' + (HG_page() + 1) + ' 页）\n发布页：' + (HG_get('hgPub') || HG_pubDef()));
  return '';
}

function HG_reset() {
  HG_set('hgRssLine', HG_def());
  HG_set('hgChk_t', '0');
  HG_toast('✓ 已恢复默认线路：' + HG_host(HG_def()));
  HG_re();
  return '';
}

function HG_refresh() { HG_re(); return ''; }

function HG_noopText() { return ''; }
function HG_noopBtn1() { return ''; }
function HG_noopBtn2() { return ''; }

function login() {
  HG_toast('✓ 黄果短剧免登录，游客可直接浏览与播放');
  return 'ok';
}

