    // 从用户当前选中的线路开始试，失败再按顺序兜底（保证点哪条就走哪条）
    var k = hi, tried = 0;
    function tryHost() {
      if (tried >= hosts.length) {
        loading = false;
        cover.className = '';
        show('所有线路都取不到播放地址，请到书源登录界面「🧭 获取线路 → ⏱ 测速排序」后重开。');
        return;
      }
      var idx = k % hosts.length;
      show('获取第 ' + ep + ' 集地址…（线路 ' + (idx + 1) + '/' + hosts.length + '：' + hostName(hosts[idx]) + '）');
      postJson(apiFor(hosts[idx], ep), function (u) {
        hi = idx;
        paintLine();
        loading = false;
        attach(u, autoplay !== false);
      }, function (m) {
        k++;
        tried++;
        tryHost();
      });
    }
    tryHost();
  }

  $('play').onclick = function () { cover.className = 'hide'; start(cur, true); };
  $('prev').onclick = function () { if (cur > 1) start(cur - 1, true); else show('已经是第一集'); };
  $('next').onclick = function () { if (cur < total) start(cur + 1, true); else show('已经是最后一集'); };
  $('reload').onclick = function () { loading = false; retry = 0; start(cur, true); };
  $('fs').onclick = function () {
    try {
      if (document.fullscreenElement || document.webkitFullscreenElement) {
        (document.exitFullscreen || document.webkitExitFullscreen).call(document);
      } else {
        var f = stage.requestFullscreen || stage.webkitRequestFullscreen;
        if (f) f.call(stage);
        else show('当前环境不支持全屏');
      }
    } catch (e) { show('全屏失败：' + e.message); }
  };
  v.addEventListener('loadedmetadata', function () {
    try {
      if (v.videoHeight > v.videoWidth && v.videoWidth > 0) stage.className = 'port';
      else stage.className = '';
    } catch (e) {}
  });
  v.addEventListener('ended', function () {
    /* 没有下一集就停：最后一集播完不做任何后续动作 */
    if (cur >= total) {
      show('已经是最后一集，播放结束');
      return;
    }
    if (autoOn) {
      show('自动播放：即将播放第 ' + (cur + 1) + ' 集…');
      start(cur + 1, true);
    } else {
      show('本集播放结束（自动连播已关）');
    }
  });
  v.addEventListener('error', function () {
    if (!hls) show('视频加载失败，可点「🔄 换直链」重试');
  });

  /* ---------------- 初始化 ---------------- */
  var savedSpeed = parseInt(loadPref('hgSpeedIdx', '0'), 10) || 0;
  speedIdx = Math.max(0, Math.min(SPEEDS.length - 1, savedSpeed));
  autoOn = loadPref('hgAuto', '1') !== '0';
  renderLines();
  renderSpeeds();
  renderEps();
  paintAuto();
  loadCover();
  if (D.autoplay) { start(cur, true); }
})();
</script>
</body>
</html>
";
